// swift-tools-version:6.0
import PackageDescription

let package = Package(
    name: "Olaz",
    platforms: [.macOS("26.0")],
    targets: [
        // Rust core as a universal static library + UniFFI C header. Built by scripts/build-rust.sh (git-ignored output):
        // run it once before `swift build` on a fresh checkout.
        .binaryTarget(
            name: "OlazCoreFFI",
            path: "rust/build/OlazCoreFFI.xcframework"
        ),
        // UniFFI-generated Swift bindings (Sources/OlazCore/OlazCore.swift, committed; regenerated by build-rust.sh).
        // Swift 5 mode for this target only: generated code is not written for Swift 6 strict concurrency.
        .target(
            name: "OlazCore",
            dependencies: ["OlazCoreFFI"],
            path: "Sources/OlazCore",
            swiftSettings: [.swiftLanguageMode(.v5)],
            linkerSettings: [
                // Needed by the Rust static library (rustls-native-certs, system roots).
                .linkedFramework("Security"),
                .linkedFramework("CoreFoundation"),
                .linkedLibrary("resolv")
            ]
        ),
        .executableTarget(
            name: "Olaz",
            dependencies: ["OlazCore"],
            path: "Sources/Olaz",
            resources: [.copy("JSModules"), .copy("Resources")]
        ),
        .testTarget(
            name: "OlazTests",
            dependencies: ["Olaz", "OlazCore"],
            path: "Tests/OlazTests"
        )
    ]
)
